package spendfold

import (
	"testing"
	"time"
)

func ts(s string) time.Time {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		panic(err)
	}
	return t
}

func TestWindowBoundaries(t *testing.T) {
	since, until := ts("2026-08-01T00:00:00Z"), ts("2026-08-02T00:00:00Z")
	got := Fold([]Entry{
		{"a", ts("2026-08-01T00:00:00Z"), 1},    // exactly since: in
		{"a", ts("2026-08-02T00:00:00Z"), 100},  // exactly until: out
		{"b", ts("2026-07-31T23:59:59Z"), 100},  // before: out
		{"b", ts("2026-08-01T12:00:00Z"), 2},    // inside: in
	}, since, until)
	if len(got) != 2 || got["a"] != 1 || got["b"] != 2 {
		t.Fatalf("boundaries: %v", got)
	}
}

func TestZonesAreInstants(t *testing.T) {
	since, until := ts("2026-08-01T00:00:00Z"), ts("2026-08-02T00:00:00Z")
	got := Fold([]Entry{
		{"a", ts("2026-08-01T02:00:00+02:00"), 3}, // the same instant as since: in
		{"a", ts("2026-08-01T22:00:00-04:00"), 4}, // 02:00Z next day: out
	}, since, until)
	if len(got) != 1 || got["a"] != 3 {
		t.Fatalf("zones: %v", got)
	}
}

func TestAbsentRootsAndUnsortedInput(t *testing.T) {
	since, until := ts("2026-08-01T00:00:00Z"), ts("2026-08-02T00:00:00Z")
	got := Fold([]Entry{
		{"late", ts("2026-08-05T00:00:00Z"), 9},
		{"a", ts("2026-08-01T18:00:00Z"), 2},
		{"a", ts("2026-08-01T06:00:00Z"), 1},
	}, since, until)
	if _, there := got["late"]; there {
		t.Fatalf("a root with no spend in the window must be absent: %v", got)
	}
	if got["a"] != 3 {
		t.Fatalf("unsorted entries must still sum: %v", got)
	}
}

func TestRoundingToCents(t *testing.T) {
	since, until := ts("2026-08-01T00:00:00Z"), ts("2026-08-02T00:00:00Z")
	at := ts("2026-08-01T01:00:00Z")
	got := Fold([]Entry{
		{"up", at, 0.006}, {"down", at, 0.004}, {"neg", at, -0.006},
		{"sum", at, 0.004}, {"sum", at, 0.004}, // 0.008 → 0.01: round the total, not each entry
	}, since, until)
	if got["up"] != 0.01 || got["down"] != 0 || got["neg"] != -0.01 || got["sum"] != 0.01 {
		t.Fatalf("rounding: %v", got)
	}
}

func TestEmptyWindow(t *testing.T) {
	at := ts("2026-08-01T00:00:00Z")
	if got := Fold([]Entry{{"a", at, 1}}, at, at); len(got) != 0 {
		t.Fatalf("since == until holds nothing: %v", got)
	}
}

