package priceladder

import (
	"math"
	"testing"
)

func close(a, b float64) bool { return math.Abs(a-b) < 1e-9 }

func TestLongestPrefixWins(t *testing.T) {
	usd, ok := Cost("gpt-5-mini-2026-01", 1_000_000, 0, 0)
	if !ok || !close(usd, 0.25) {
		t.Fatalf("gpt-5-mini must win over gpt-5: %v %v", usd, ok)
	}
	usd, ok = Cost("gpt-5-turbo", 1_000_000, 0, 0)
	if !ok || !close(usd, 1.25) {
		t.Fatalf("gpt-5 is a plain prefix of gpt-5-turbo: %v %v", usd, ok)
	}
	usd, ok = Cost("gpt-5", 0, 1_000_000, 0)
	if !ok || !close(usd, 10.00) {
		t.Fatalf("exact name matches its own entry: %v %v", usd, ok)
	}
}

func TestCacheReadsBillAtATenth(t *testing.T) {
	usd, ok := Cost("sonnet-5", 1_000_000, 200_000, 500_000)
	// 3.00 + 0.2*15.00 + 0.5*(3.00/10) = 3.00 + 3.00 + 0.15
	if !ok || !close(usd, 6.15) {
		t.Fatalf("cache math: %v %v", usd, ok)
	}
}

func TestUnknownAndZero(t *testing.T) {
	if _, ok := Cost("claude-haiku", 5, 5, 5); ok {
		t.Fatal("no entry prefixes claude-haiku")
	}
	if _, ok := Cost("", 1, 1, 1); ok {
		t.Fatal("the empty model matches nothing")
	}
	usd, ok := Cost("gpt-5-nano", 0, 0, 0)
	if !ok || usd != 0 {
		t.Fatalf("zero tokens cost zero: %v %v", usd, ok)
	}
}

