package sched

// FreeBetween returns the gaps inside day that busy leaves open.
// busy must already be Normalize'd; this walk assumes sorted,
// non-overlapping, non-touching intervals and nothing else.
func FreeBetween(busy []Interval, day Interval) []Interval {
	free := []Interval{}
	cur := day.Start
	for _, b := range busy {
		if b.End <= day.Start || b.Start >= day.End {
			continue
		}
		if b.Start > cur {
			free = append(free, Interval{cur, min(b.Start, day.End)})
		}
		if b.End > cur {
			cur = b.End
		}
	}
	if cur < day.End {
		free = append(free, Interval{cur, day.End})
	}
	return free
}

