package lru

// Cache is a fixed-capacity least-recently-used cache. Get and Put
// both count as use: the entry touched longest ago is the one evicted.
type Cache struct {
	cap   int
	vals  map[string]int
	order []string // most recently used first
}

func New(capacity int) *Cache {
	return &Cache{cap: capacity, vals: map[string]int{}}
}

func (c *Cache) Get(k string) (int, bool) {
	v, ok := c.vals[k]
	if ok {
		c.touch(k)
	}
	return v, ok
}

func (c *Cache) Put(k string, v int) {
	if _, ok := c.vals[k]; ok {
		c.vals[k] = v
		return
	}
	if len(c.vals) >= c.cap {
		last := c.order[len(c.order)-1]
		delete(c.vals, last)
		c.order = c.order[:len(c.order)-1]
	}
	c.vals[k] = v
	c.order = append([]string{k}, c.order...)
}

func (c *Cache) Len() int { return len(c.vals) }

func (c *Cache) touch(k string) {
	for i, o := range c.order {
		if o == k {
			c.order = append(c.order[:i], c.order[i+1:]...)
			break
		}
	}
	c.order = append([]string{k}, c.order...)
}

