package lru

import "testing"

func TestBasics(t *testing.T) {
	c := New(2)
	c.Put("a", 1)
	c.Put("b", 2)
	if v, ok := c.Get("a"); !ok || v != 1 {
		t.Fatalf("a: %v %v", v, ok)
	}
	c.Put("c", 3) // evicts b: a was just used
	if _, ok := c.Get("b"); ok {
		t.Fatal("b must be evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("len: %d", c.Len())
	}
}

func TestGetRefreshesRecency(t *testing.T) {
	c := New(3)
	c.Put("a", 1)
	c.Put("b", 2)
	c.Put("c", 3)
	c.Get("a")
	c.Put("d", 4) // evicts b
	if _, ok := c.Get("b"); ok {
		t.Fatal("b was the least recently used")
	}
	if _, ok := c.Get("a"); !ok {
		t.Fatal("a was refreshed by Get")
	}
}

func TestUpdateRefreshesRecency(t *testing.T) {
	c := New(3)
	c.Put("a", 1)
	c.Put("b", 2)
	c.Put("c", 3)
	c.Put("a", 10) // an update is a use
	c.Put("d", 4)  // evicts b, the least recently used
	if _, ok := c.Get("b"); ok {
		t.Fatal("b was the least recently used, not a")
	}
	if v, ok := c.Get("a"); !ok || v != 10 {
		t.Fatalf("a must survive with its new value: %v %v", v, ok)
	}
	if c.Len() != 3 {
		t.Fatalf("len: %d", c.Len())
	}
}

