package shellwords

import "errors"

var ErrUnterminated = errors.New("unterminated quote")

// Split cuts s into fields the way a POSIX-ish shell reads a command
// line, with no expansion of any kind:
//   - Unquoted runs split on spaces and tabs; runs of separators
//     produce no empty fields.
//   - Single quotes are literal to the closing quote, backslashes
//     included.
//   - Double quotes are literal except \" and \\, which yield " and \;
//     any other backslash stays as written.
//   - Outside quotes a backslash escapes the next byte, spaces and
//     quotes included; a lone trailing backslash is a literal one.
//   - Adjacent pieces with no separator between them are ONE field:
//     a"b c"'d' is the single field `ab cd`.
//   - "" and '' contribute an empty piece — alone they are an empty
//     field.
//   - A quote left open returns ErrUnterminated.
