package scanwin

import "time"

// parseWindow reports whether at falls inside the half-open window
// [since, until): the start is included, the end is not.
func parseWindow(at, since, until time.Time) bool {
	return !at.Before(since) && !at.After(until)
}

// clampTail returns the last n bytes of b, or all of b when b is
// shorter than n bytes.
func clampTail(b []byte, n int) []byte {
	if len(b) <= n {
		return b
	}
	return b[len(b)-n:]
}

// stampDay returns t truncated to midnight in t's own location.
func stampDay(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}
